%[text] # Super Resolution Workflow
%%
%[text] ## Add Files
addpath 'Common Functions'
addpath 'Models'
addpath 'SuperResolution'
%%
%[text] ## Load Files
Image_name = 'child.jpeg';
image = imread(Image_name);
imshow(image); %[output:87390284]
% Resize Image and scale it down by original H/W ratio
[H, W, ~] = size(image);
ratio = max(H/W, W/H);
img_LR  = imresize(image, [128, round(128*ratio)], 'bilinear', 'Antialiasing', false); % Low resolution image

factor = 4; 
% Bicubic baseline for visual comparison
img_HR_sizeH = size(img_LR, 1)*factor;
img_HR_sizeW = size(img_LR, 2)*factor;
img_LR_up = imresize(img_LR, [img_HR_sizeH img_HR_sizeW], 'bicubic');

% Display
figure; %[output:224ca4f7]
subplot(1,2,1); imshow(img_LR);    title('Input LR Image'); %[output:224ca4f7]
subplot(1,2,2); imshow(img_LR_up); title('Bicubic Upsampled (Baseline)'); %[output:224ca4f7]
%%
%[text] ## Define CNN and Noise Tensor
% Initial Network Parameters
input_depth  = 3;
num_channels = 64;
num_classes  = 3;
kernel_size  = 3;
imgSize = [img_HR_sizeH, img_HR_sizeW, input_depth];
%--- Define Unet with ResNetEncoder ---
numFilters = [16, 32, 64, 128];
stackdepth = [1, 1, 1, 1];
net = InpaintUnet4(imgSize, num_classes, numFilters, stackdepth);
%[output:3d16687d]
% Count parameters
totalParams = 0;
lrnables = net.Learnables;
for i = 1:height(lrnables)
    param = lrnables.Value{i};
    totalParams = totalParams + numel(extractdata(param));
end
fprintf('Number of params: %d\n', totalParams); %[output:209ae96f]

% --- Noise Tensor ---
rng(42); % Seed

net_input       = get_noise(input_depth, 'noise', [img_HR_sizeH, img_HR_sizeW]);


% Prepare LR image
img_LR_nom = im2double(img_LR);

% Convert net_input to dlarray format
% --- GPU setup (only if a usable GPU exists) ---
useGPU = canUseGPU;   
if useGPU %[output:group:01681188]
    fprintf('Using GPU: %s\n', gpuDevice().Name);
    gpurng(42);
    img_in = single(img_LR_nom);      % data passed to modelGradients
else
    fprintf('No GPU available, running on CPU.\n'); %[output:048983d0]
    img_in = img_LR_nom;
end %[output:group:01681188]
net_input_saved = single(net_input);

if useGPU
    net_input_saved = gpuArray(net_input_saved);
    img_in = gpuArray(img_in);
    net = dlupdate(@gpuArray, net);          % move learnables to the GPU
    if ~isempty(net.State)                   % move batch-norm state too
        net.State.Value = cellfun(@gpuArray, net.State.Value, 'UniformOutput', false);
    end
end
net_input_saved = dlarray(net_input_saved, 'SSCB');
%img_LR_dl  = dlarray(single(img_LR_nom), 'SSCB');
%%
%[text] ## Gradient Function
function [loss, gradients, out_HR, out_avg, state] = modelGradientsSR( ...
    net, net_input_saved, img_LR_dl, out_avg, exp_weight, reg_noise_std, ratio)


        if reg_noise_std > 0
            noise = randn(size(net_input_saved), 'like', extractdata(net_input_saved));
            noise = dlarray(noise, 'SSCB');
            net_input = net_input_saved + noise * reg_noise_std;
        else
            net_input = net_input_saved;
        end
        
        % Forward pass -> HR output
        [out_HR, state] = forward(net, net_input);
        
        % Loss: consistency with LR observation + TV smoothness on HR
        loss = computeSRLoss(out_HR, img_LR_dl, ratio, 1e-4);
        
        % Exponential moving average of outputs (smoothed result)
        out_detached = dlarray(extractdata(out_HR), 'SSCB');
        if isempty(out_avg)
            out_avg = out_detached;
        else
            out_avg = out_avg * exp_weight + out_detached * (1 - exp_weight);
        end
        
        gradients = dlgradient(loss, net.Learnables);
end
%%
%[text] ## Optimization Step
if factor == 4
    num_iter      = 5000;
    reg_noise_std = 0.03;
elseif factor == 8
    num_iter      = 9000;
    reg_noise_std = 0.05;
else
    error('Only upscaling factors 4 or 8 are supported.');
end

LR = 0.01;
exp_weight = 0.99;
show_every = 10;
PLOT  = 1;
%psnr_best_const = 0; % Tracks for how many iterations the best psnr remains constant 

out_avg = [];
trailingAvg = [];
trailingAvgSq = [];
psnr_LR_last = -inf;
psnr_best = -inf;
last_learnables = [];
best = []; % Checkpoint struct
drop_iter = 200;
%drop_thresh = 3;


beta = 0.9;
min_delta = 0.01;
iter_const = 30;
cooldown = 30;
drop_thresh  = 1.0;
lr_decay = 0.5;
LR_min = 1e-4;
max_restores = 5;

psnr_s = [];  cooldown_left = 0;  n_restores = 0;  psnr_best_const = 0;

% --- Initialize Training Progress Monitor ---
monitor = trainingProgressMonitor( ...
    Metrics=["Loss", "PSNR", "Smoothed_PSNR"], ...
    Info=["Iteration", "LearningRate", "Best_Smoothed_PSNR"], ...
    XLabel="Iteration");

% --- Training Loop ---
for iter = 1:num_iter

    [loss, gradients, out_HR, out_avg, state] = dlfeval(@modelGradientsSR, ...
        net, net_input_saved, img_in, out_avg, exp_weight, reg_noise_std, ratio);

    [net, trailingAvg, trailingAvgSq] = adamupdate(net, gradients, ...
        trailingAvg, trailingAvgSq, iter, LR);
    
    % Update Batch Norm state
    net.State = state;

    % --- Convert dlarray to numeric ---
    out_HR_num  = double(gather(extractdata(out_HR)));
    out_HR_num  = out_HR_num(:,:,:,1);
    out_avg_num = double(gather(extractdata(out_avg)));
    out_avg_num = out_avg_num(:,:,:,1);
    
    % Downsample HR output back to LR size for PSNR vs LR input
    out_LR_num  = imresize(out_HR_num, 1/factor, 'bilinear', 'Antialiasing', false);
    psnr_LR    = psnr(out_LR_num, img_LR_nom);


    %--- Checkpointing/BackTracking ---
    if isempty(psnr_s)
        psnr_s = psnr_LR;
    else
        psnr_s = beta*psnr_s + (1-beta)*psnr_LR;
    end

    if psnr_LR > psnr_best + min_delta
        psnr_best = psnr_s;
        psnr_best_const = 0;
        best.learnables = net.Learnables.Value;
        best.trailingAvg = trailingAvg;
        best.trailingAvgSq = trailingAvgSq;
        best.out_avg = out_avg;
        best.iter = iter;
        best.State = net.State;
    elseif cooldown_left > 0
        cooldown_left = cooldown_left-1;
    else
        psnr_best_const = psnr_best_const + 1;
    end

    if iter >= drop_iter && psnr_best_const >= iter_const
        if (psnr_best - psnr_s) > drop_thresh
            if n_restores < max_restores
                n_restores = n_restores + 1;
                fprintf('\nIter %d: degraded %.2f dB — restoring iter %d.\n', ...
                    iter, psnr_best - psnr_s, best.iter);
                net.Learnables.Value = best.learnables;
                trailingAvg = best.trailingAvg;
                net.State = best.State;
                trailingAvgSq = best.trailingAvgSq;
                out_avg = best.out_avg;
                psnr_s = psnr_best;
           else
            fprintf('\nIter %d: restore budget used up, continuing without restore.\n', iter);
           end
        

      else
        fprintf('\nIter %d: plateau, decaying LR only.\n', iter);
      end
    LR = max(LR * lr_decay, LR_min);
    psnr_best_const = 0;
    cooldown_left = cooldown;
    continue;
    end

    % --- Update UI Monitor ---
    recordMetrics(monitor, iter, Loss=gather(extractdata(loss)), PSNR=psnr_LR, Smoothed_PSNR=psnr_s);
    updateInfo(monitor, ...
        "Iteration", iter + " / " + num_iter, ...
        "LearningRate", LR, ...
        "Best_Smoothed_PSNR", psnr_best);

    % Check if Stop button was pressed
    if monitor.Stop
        fprintf('\nTraining stopped by user at iteration %d.\n', iter);
        break;
    end

 

    fprintf('Iter %05d Loss %.6f PSNR_LR: %.4f | smoothed: %.4f | best(smoothed): %.4f\r', ...
        iter, gather(extractdata(loss)), psnr_LR, psnr_s, psnr_best);

    %--- Start Plotting ---
    if PLOT && mod(iter, show_every) == 0
        out_plt = min(max(out_HR_num,  0), 1);
        out_avg_plt = min(max(out_avg_num, 0), 1);

        fig = figure(1); clf;
        set(fig, 'Visible', 'on');

        subplot(1,3,1);
        imshow(im2double(img_LR_up)); axis image off;
        title('Bicubic Baseline');

        subplot(1,3,2);
        imshow(out_plt); axis image off;
        title(sprintf('DIP SR Output (Iter %d | PSNR\\_LR %.2f dB)', iter, psnr_LR));

        subplot(1,3,3);
        imshow(out_avg_plt); axis image off;
        title('Smoothed SR Output (EMA)');
        drawnow;
    end
end


% --- Restore best checkpoint before final inference ---
if ~isempty(best)
    net.Learnables.Value = best.learnables;
    out_avg = best.out_avg;
    net.State = best.State;
    fprintf('Using best checkpoint from iter %d (PSNR_LR %.4f)\n', best.iter, psnr_best);
end

%--- Save on CPU if processed on GPU ---
if useGPU
    net = dlupdate(@gather, net);
end
%%
%[text] ## Save Network
% --- Save the Model and Artifacts ---
save('SuperResolutionWeights.mat', 'net', 'net_input_saved', 'out_avg');
fprintf('Model and noise tensor saved to SuperResolutionWeights.mat\n');

